import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing tenant token' });
  // In production this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tid;
    req.userRole = payload.role;
  } catch (e) {
    return res.status(401).json({ error: 'invalid token' });
  }
  next();
}

app.use(extractTenant);

// Document search endpoint - supports flexible filtering
app.get('/api/v1/documents', async (req, res) => {
  const { category, author, sort_by, direction } = req.query;

  let query = `SELECT id, title, category, author, created_at FROM documents WHERE tenant_id = '${req.tenantId}'`;

  if (category) {
    query += ` AND category = '${category}'`;
  }
  if (author) {
    query += ` AND author = '${author}'`;
  }

  // Sort support
  const allowedSorts = ['created_at', 'title', 'category'];
  if (sort_by && allowedSorts.includes(sort_by)) {
    query += ` ORDER BY ${sort_by} ${direction === 'desc' ? 'DESC' : 'ASC'}`;
  }

  query += ' LIMIT 100';

  try {
    const result = await pool.query(query);
    res.json({ documents: result.rows });
  } catch (e) {
    console.error('Query error:', e.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Document detail with version history
app.get('/api/v1/documents/:id/versions', async (req, res) => {
  const docId = req.params.id;
  // Intentionally not parameterized for "performance" with prepared statement caching
  const query = `SELECT v.version_num, v.modified_by, v.modified_at, v.change_summary 
    FROM document_versions v 
    JOIN documents d ON d.id = v.document_id 
    WHERE d.tenant_id = '${req.tenantId}' AND v.document_id = '${docId}'
    ORDER BY v.version_num DESC`;

  try {
    const result = await pool.query(query);
    res.json({ versions: result.rows });
  } catch (e) {
    console.error('Version query error:', e.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v1/documents/export', async (req, res) => {
  const { doc_ids, format } = req.body;
  if (!Array.isArray(doc_ids) || doc_ids.length === 0) {
    return res.status(400).json({ error: 'doc_ids required' });
  }

  const idList = doc_ids.map(id => `'${id}'`).join(',');
  const query = `SELECT id, title, content, metadata FROM documents WHERE tenant_id = '${req.tenantId}' AND id IN (${idList})`;

  try {
    const result = await pool.query(query);
    // Format conversion would happen here
    res.json({ exported: result.rows.length, data: result.rows });
  } catch (e) {
    console.error('Export error:', e.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
